        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Negative."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/MedicationStatement/medication-statement-1",
      "resource": {
        "resourceType": "MedicationStatement",
        "id": "medication-statement-1",
        "status": "active",
        "medicationCodeableConcept": {
          "text": "Paracetamol (Panadol)"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "dosage": [
          {
            "text": "Patient reports using 1 g twice daily as needed; plan is to continue up to 1 g four times daily as needed, maximum 4 g/day.",
            "asNeededBoolean": true,
